<?php require __DIR__.'/_init.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$key=trim($_POST['identity']??'');$bucket=hash('sha256',($_SERVER['REMOTE_ADDR']??'').$key);$_SESSION['attempts'][$bucket]=$_SESSION['attempts'][$bucket]??[];$_SESSION['attempts'][$bucket]=array_filter($_SESSION['attempts'][$bucket],fn($t)=>$t>time()-900);if(count($_SESSION['attempts'][$bucket])>=8)$error='Too many attempts. Wait 15 minutes and try again.';else{$s=db()->prepare('SELECT id,full_name,username,email,role,password_hash FROM users WHERE username=? OR email=?');$s->execute([$key,$key]);$u=$s->fetch();if($u&&password_verify($_POST['password']??'',$u['password_hash'])){session_regenerate_id(true);unset($u['password_hash']);$_SESSION['user']=$u;$_SESSION['attempts'][$bucket]=[];header('Location: /dashboard.php');exit;}$_SESSION['attempts'][$bucket][]=time();$error='The username/email or password is incorrect.';}} page_start('Sign in');?><section class="form-wrap"><div class="eyebrow">WELCOME BACK</div><h1>Sign in</h1><p>Your campus support desk is one step away.</p><?php if($error)echo '<p class="error">'.e($error).'</p>';?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Username or email<input name="identity" autocomplete="username" required></label><label>Password<input type="password" name="password" autocomplete="current-password" required></label><button class="button">Sign in →</button></form><p>New here? <a href="/signup.php">Create an account</a></p></section><?php page_end();?>
